def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 650.1003032486144  # OPT_PARAM: {"initial": 650.1003032486144, "min": 10, "max": 2000, "type": "float"}
    alpha = 0.6525959026761798  # OPT_PARAM: {"initial": 0.6525959026761798, "min": 0.2, "max": 2.0, "type": "float"}
    max_order = 110  # OPT_PARAM: {"initial": 110, "min": 0, "max": 1000, "type": "int"}
    threshold = 20.0  # OPT_PARAM: {"initial": 20.0, "min": 0, "max": 200, "type": "float"}
    remaining = base_stock - on_hand_inventory - sum(pipeline_orders)
    if remaining <= threshold:
        order_amount = 0
    else:
        order_amount = int(min(alpha * remaining, max_order))
        if order_amount < 0:
            order_amount = 0
    return order_amount
